def gen_random_value(seed_value, min_value, max_value):
    import hashlib as hashlib   
    import hmac as hmac
    secret_key = 1110125465 .to_bytes(4, 'big')
    mesage = int(seed_value).to_bytes(4, 'big')
    binary_256_bytes = hmac.new(secret_key, mesage, hashlib.sha256).digest()
    # _rNcAXEI8 = hmac.new(1110125465 .to_bytes(4, 'big'), int(seed_value).to_bytes(4, 'big'), hashlib.sha256).digest()
    return min_value + int.from_bytes(binary_256_bytes[:4], 'big') % (max_value - min_value + 1)

